-- Seed the durable photo registry from dish-catalog.json.
--
-- Storage is a cache: these rows carry the original (resized) source URL for
-- every catalog dish, so `recache-images` can rebuild the bucket after a loss.
-- `storage_path` is the content-hashed object already uploaded by supabase.yml.
on conflict (kind, key, source_url) do update set
  source_page = excluded.source_page,
  license = excluded.license,
  attribution = excluded.attribution,
  sha256 = excluded.sha256,
  storage_bucket = excluded.storage_bucket,
  storage_path = excluded.storage_path,
  verified = excluded.verified;
